use std::collections::HashMap;

fn main() {
    println!("Bismillah");
}

fn roman_to_decimal(roman: &str) -> u32 {
    let mut map = HashMap::new();
    map.insert('I', 1);
    map.insert('V', 5);
    map.insert('X', 10);
    map.insert('L', 50);
    map.insert('C', 100);
    map.insert('D', 500);
    map.insert('M', 1000);

    let mut sum = 0;
    let mut prev_value = 0;

    for c in roman.chars().rev() {
        let value = *map.get(&c).unwrap();

        if value < prev_value {
            sum -= value;
        } else {
            sum += value;
        }

        prev_value = value;
    }

    return sum;
}

