}

impl Storage<'_> {
    pub(crate) fn get(&self, path: &str) -> Result<Blob, Error> {
        match self {
            Self::Database(db) => db.get(path),
            Self::S3(s3) => s3.get(path),
        }
    }

    pub(crate) fn put(&mut self, blob: Blob) -> Result<(), Error> {
        match self {
            Self::Database(db) => db.put(blob),
            Self::S3(s3) => s3.put(blob),
        }
    }

    pub(crate) fn delete(&mut self, path: &str) -> Result<(), Error> {
        match self {
            Self::Database(db) => db.delete(path),
            Self::S3(s3) => s3.delete(path),
        }
    }

    pub(crate) fn read_to_end<R>(&mut self, reader: R) -> Result<Vec<u8>, Error>
    where
        R: Read,
    {
        let mut buf = Vec::new();
        reader.read_to_end(&mut buf)?;
        Ok(buf)
    }

    pub(crate) fn write_all<W>(&mut self, writer: W, data: &[u8]) -> Result<(), Error>
    where
        W: Write,
    {
        writer.write_all(data)?;
        Ok(())
    }
}

